.aj-layout-app-header{position:relative;z-index:35;min-height:64px!important;width:100%;display:grid!important;grid-template-columns:42px minmax(0,1fr) 42px!important;gap:10px;align-items:center;padding:8px 14px!important;background:#10233f!important;color:#fff!important;box-shadow:0 4px 14px rgba(16,35,63,.18);font-family:Inter,"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
.aj-layout-app-header.aj-public{grid-template-columns:minmax(0,1fr)!important;padding:10px 18px!important}
.aj-layout-brand{min-width:0;display:flex;align-items:center;gap:9px}.aj-layout-brand img{width:28px;height:28px;flex:none;object-fit:contain;filter:brightness(0) invert(1)}
.aj-layout-brand-copy{min-width:0;display:flex;flex-direction:column;justify-content:center}.aj-layout-brand-copy strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;line-height:1.16;letter-spacing:-.02em;font-weight:800}.aj-layout-brand-copy small{font-size:9px;margin-top:2px;letter-spacing:.075em;text-transform:uppercase;font-weight:800;opacity:.74}
.aj-layout-icon-button{width:40px;height:40px;display:grid;place-items:center;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer;padding:0}.aj-layout-icon-button:hover{background:#ffffff15}.aj-layout-icon-button:focus-visible,.aj-layout-drawer button:focus-visible{outline:3px solid #9bc1fa;outline-offset:2px}
.aj-layout-icon-button.app-menu-button{display:grid;place-content:center;gap:4px}.aj-layout-icon-button.app-menu-button span{display:block;width:20px;height:2px;border-radius:9px;background:currentColor}
.aj-layout-icon-button.app-notifications{position:relative;justify-self:end}.aj-layout-icon-button.app-notifications svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.aj-layout-badge{position:absolute;top:3px;right:1px;min-width:17px;height:17px;padding:0 3px;border:2px solid #10233f;border-radius:999px;display:grid;place-items:center;background:#ef4444;color:#fff;font-size:9px;font-weight:850}
.aj-layout-app-header.aj-public .app-menu-button,.aj-layout-app-header.aj-public .app-notifications{display:none!important}

.aj-layout-titlebar{width:100%;min-height:38px;display:flex;align-items:center;padding:10px 18px;border-bottom:1px solid #dbe3ee;background:#fff;color:#10233f;font:700 13px/1.35 Inter,"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
.aj-layout-titlebar strong{font-weight:700;font-size:13px}

/* solicitacoes.cliente.minhas_solicitacoes · Cliente · Minhas solicitações */
.requests-page{display:grid;gap:14px}.requests-summary{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:2px 0}.requests-summary h2{margin:0 0 4px;color:var(--primary);font-size:18px}.requests-summary p{margin:0;color:var(--muted);font-size:12px;line-height:1.45}.requests-total{display:grid;min-width:34px;height:30px;place-items:center;padding:0 9px;border-radius:999px;background:#e7f0ff;color:var(--primary);font-size:11px;font-weight:900}.requests-tabs{overflow:auto;scrollbar-width:none}.requests-tabs::-webkit-scrollbar{display:none}.requests-tabs button{white-space:nowrap}.requests-tabs button span{display:inline-grid;min-width:18px;height:18px;place-items:center;margin-left:5px;padding:0 5px;border-radius:999px;background:rgba(16,35,63,.08);font-size:9px;font-weight:900}.requests-tabs button.active span{background:rgba(255,255,255,.25)}.requests-list{display:grid;gap:9px}.request-card{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto 12px;gap:10px;align-items:center;padding:12px 12px;border:1px solid var(--line);border-radius:13px;background:#fff;color:var(--text);text-align:left;box-shadow:0 4px 11px rgba(15,23,42,.035);cursor:pointer}.request-card[hidden]{display:none}.request-main,.request-side{display:grid;gap:4px;min-width:0}.request-main strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.request-main small,.request-side small{color:var(--muted);font-size:10px;line-height:1.35}.request-side{justify-items:end}.status-chip{display:inline-flex;align-items:center;justify-content:center;padding:5px 8px;border-radius:999px;font-size:9px;font-weight:900}.status-pending{background:#fff7e6;color:#a15c00}.status-accepted{background:#ecfdf3;color:#039855}.status-declined{background:#fff1f0;color:#b42318}.request-chevron{color:var(--muted);font-size:21px}.requests-empty{display:grid;gap:4px;text-align:center}.requests-empty strong{font-size:12px}.requests-empty span{color:var(--muted);font-size:10px}@media(min-width:720px){.request-card{padding:14px 16px}.request-main strong{font-size:14px}.request-main small,.request-side small{font-size:11px}}

.aj-layout-drawer.prototype-drawer{position:fixed!important;inset:0!important;z-index:9998!important;display:none!important;pointer-events:none}.aj-layout-drawer.prototype-drawer.open{display:block!important;pointer-events:auto}
.aj-layout-drawer .aj-layout-backdrop{position:absolute;inset:0;width:100%;border:0;background:rgba(7,16,30,.60);cursor:pointer}
.aj-layout-drawer .aj-layout-panel{position:absolute;inset:0 auto 0 0;width:min(80vw,360px);max-width:100vw;display:flex;flex-direction:column;overflow:hidden;background:#3b4a7d;color:#fff;box-shadow:12px 0 30px #0005;font-family:Inter,"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
.aj-layout-drawer .aj-layout-identity{display:flex;align-items:center;gap:13px;padding:29px 20px 17px;flex:none}.aj-layout-avatar{width:52px;height:52px;flex:none;display:grid;place-items:center;border:2px solid #ffffff40;border-radius:50%;background:#dbeafe;color:#1e3a8a;font-size:18px;font-weight:850}
.aj-layout-status{min-height:46px;display:flex;justify-content:space-between;align-items:center;gap:9px;margin:0 20px 10px;padding:9px 12px;border:1px solid #ffffff33;border-radius:10px;background:#ffffff12;color:#fff;cursor:pointer;font-size:12px;text-align:left}.aj-layout-status[hidden]{display:none!important}.aj-layout-status .aj-status-dot{width:9px;height:9px;flex:none;border-radius:50%;background:#4ade80}.aj-layout-drawer[data-disponibilidade="offline"] .aj-status-dot{background:#b8c0cb}.aj-layout-status b{font-size:12px}.aj-layout-status small{font-size:10px;display:block;color:#bfd4f4}.aj-layout-status-copy{flex:1}
.aj-layout-drawer .drawer-nav{display:block;min-height:0;overflow-y:auto;overflow-x:hidden;flex:1;overscroll-behavior:contain;padding-bottom:8px}.aj-layout-drawer .drawer-nav button{width:100%;min-height:49px;display:flex;align-items:center;gap:13px;padding:12px 20px;border:0;border-bottom:1px solid #ffffff1d;background:transparent;color:#fff;text-align:left;font:500 13px Inter,"Segoe UI",Arial,sans-serif;cursor:pointer}.aj-layout-drawer .drawer-nav button:hover{background:#ffffff15}.aj-layout-drawer .drawer-nav svg{width:19px;height:19px;flex:none;stroke:#bcccec;fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}.aj-layout-drawer .drawer-nav button strong{font-weight:650;flex:1}.aj-layout-drawer .drawer-nav .aj-subitem{min-height:41px;padding-left:49px;font-size:12px;background:#00000013}.aj-layout-drawer .drawer-nav .aj-subitem svg{width:15px;height:15px}.aj-layout-drawer .drawer-nav .aj-item-hint{margin-left:auto;font-size:10px;opacity:.8}.aj-layout-drawer .drawer-nav .aj-menu-group{background:#ffffff0c}.aj-layout-drawer .drawer-nav .aj-menu-group b{font-size:12px}
.aj-layout-drawer [data-aj-group-content="estudante"],.aj-layout-drawer [data-aj-group-content="escritorio"]{display:none!important}.aj-layout-drawer[data-estudante-menu="aberto"] [data-aj-group-content="estudante"]{display:flex!important}.aj-layout-drawer[data-escritorio-menu="aberto"] [data-aj-group-content="escritorio"]{display:flex!important}
.aj-layout-drawer[data-plano="sem_plano"] [data-aj-protegido],.aj-layout-drawer[data-plano="pendente"] [data-aj-protegido],.aj-layout-drawer[data-plano="vencido"] [data-aj-protegido]{opacity:.52}
.aj-layout-drawer[data-oab="restricted"] [data-aj-oab-only="enabled"]{opacity:.5}
.aj-layout-drawer[data-permissao="auditor"] [data-aj-admin-only="gestor"],.aj-layout-drawer[data-permissao="operador"] [data-aj-admin-only="gestor"]{opacity:.5}
.aj-layout-drawer[data-vinculo-escritorio="sem_escritorio"] [data-aj-requer-escritorio],.aj-layout-drawer[data-vinculo-escritorio="convite_pendente"] [data-aj-requer-escritorio],.aj-layout-drawer[data-vinculo-escritorio="suspenso"] [data-aj-requer-escritorio]{opacity:.5}
.aj-layout-drawer .aj-layout-footer{padding:14px 20px 23px;background:#00000019;flex:none;font-size:11px}.aj-layout-footer-row{display:flex;justify-content:space-between;align-items:center;gap:10px}.aj-layout-footer button{border:0;background:transparent;color:#fff;font-size:13px;padding:6px 0;cursor:pointer}.aj-layout-footer small{font-size:10px;color:#b0c2df}.aj-layout-emergency{width:100%;margin-top:12px;padding:10px!important;border:1px solid #ffffff80!important;border-radius:99px!important;font-weight:750!important}

/* Modal de navegação: sem estilos exclusivos; utiliza a folha do componente principal. */

/* Identificação da tela isolada: sem estilos exclusivos; utiliza a folha do componente principal. */

:host {
  display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}
*, *::before, *::after { box-sizing: border-box; }
button, input, select, textarea { font: inherit; }
button { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
[hidden] { display: none !important; }
